args.query:
\d+ api.application
\d+ api.company
\d+ api.app_user
select rolname from pg_roles where rolname !~ '^pg_';
select * from api.app_user;
select grantee,table_name,privilege_type from information_schema.role_table_grants where table_schema='api' order by 2,1;
select tablename,policyname,roles,cmd,qual,with_check from pg_policies;
select relname,relrowsecurity,relforcerowsecurity,relkind,relowner::regrole,reloptions from pg_class where relnamespace='api'::regnamespace;
select tgname,tgrelid::regclass from pg_trigger where not tgisinternal;

select pg_get_functiondef(p.oid) from pg_proc p where pronamespace='priv'::regnamespace and proname in ('my_company','status_id','status_ord');
select * from api.status;
select id,number,company_id,status_id,amount from api.application order by id;
select * from api.company;

create table api.contract(
 id serial primary key,
 number text not null unique,
 application_id integer not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date,
 status text not null default 'Проект' check (status in ('Проект','Подписан'))
);
create or replace function priv.contract_check() returns trigger language plpgsql security definer set search_path=api as $$
begin
 if new.application_id is distinct from (select id from api.application where id=new.application_id and status_id=(select id from api.status where name='Одобрена')) then
  raise exception 'Договор можно заключить только по одобренной заявке';
 end if;
 return new;
end$$;
create trigger contract_check before insert or update on api.contract for each row execute function priv.contract_check();
alter table api.contract enable row level security;
create policy admin_all on api.contract for all to fund_admin using(true) with check(true);
create policy lawyer_read on api.contract for select to lawyer using(true);
create policy lawyer_ins on api.contract for insert to lawyer with check(true);
create policy lawyer_upd on api.contract for update to lawyer using(true) with check(true);
create policy applicant_read on api.contract for select to applicant using (exists(select 1 from api.application a where a.id=application_id and a.company_id=priv.my_company()));
grant select,insert,update,delete on api.contract to fund_admin;
grant select,insert,update on api.contract to lawyer;
grant select on api.contract to applicant;
grant usage on sequence api.contract_id_seq to fund_admin,lawyer;
grant select on api.application, api.company, api.status to lawyer;
create policy lawyer_read on api.application for select to lawyer using(true);
grant usage on schema api to lawyer;
grant execute on function priv.my_company() to lawyer;
update api.app_user set role='lawyer' where login='lawyer1';
create view api.limit_balance with (security_invoker=true) as
select c.name as company, c.funding_limit, ap.approved, coalesce(ct.contracted,0) as contracted,
 c.funding_limit-coalesce(ct.contracted,0) as remaining
from api.company c
join (select company_id,sum(amount) approved from api.application where status_id=(select id from api.status where name='Одобрена') group by company_id) ap on ap.company_id=c.id
left join (select a.company_id,sum(k.amount) contracted from api.contract k join api.application a on a.id=k.application_id group by a.company_id) ct on ct.company_id=c.id;
grant select on api.limit_balance to fund_admin,lawyer,applicant;
select has_schema_privilege('applicant','api','usage'), has_schema_privilege('lawyer','priv','usage');
